// Infographic overlay for the halal-certificate TikTok cut.
// Rendered transparent (ProRes 4444) and composited by FFmpeg. Timing comes from
// timeline.json (generated by tiktok-sijil-halal/pipeline/timeline.py), so every
// element lands on the word the speaker says.
import React from "react";
import {
  AbsoluteFill,
  Easing,
  Sequence,
  continueRender,
  delayRender,
  interpolate,
  spring,
  staticFile,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import TL from "./timeline.json";

const NAVY = "#0E1E3F";
const NAVY_A = "rgba(14,30,63,0.86)";
const GOLD = "#C9A24B";
const GOLD_LIT = "#E9C46A";
const WHITE = "#FFFFFF";
const BAND_TOP = 1372; // lower band: below captions, above TikTok's caption zone
const LEFT = 72;

const FONTS: [string, string, string, string][] = [
  ["Sora", "600", "normal", "sijil-halal/sora-latin-600-normal.woff2"],
  ["Sora", "700", "normal", "sijil-halal/sora-latin-700-normal.woff2"],
  ["Inter", "500", "normal", "sijil-halal/inter-latin-500-normal.woff2"],
  ["Inter", "600", "normal", "sijil-halal/inter-latin-600-normal.woff2"],
];
const fontHandle = delayRender("fonts");
Promise.all(
  FONTS.map(([family, weight, style, file]) => {
    const f = new FontFace(family, `url(${staticFile(file)})`, { weight, style });
    return f.load().then((loaded) => document.fonts.add(loaded));
  }),
).then(() => continueRender(fontHandle));

const sec = (s: number, fps: number) => Math.round(s * fps);
const useT = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  return { frame, fps, t: frame / fps };
};
const ease = Easing.out(Easing.cubic);

// Fade/rise in from `at` (seconds, relative to the Sequence) and fade out before `end`.
const useReveal = (at: number, end: number, rise = 18) => {
  const { frame, fps } = useT();
  const s = spring({ frame: frame - sec(at, fps), fps, config: { damping: 200, mass: 0.6 } });
  const out = interpolate(frame, [sec(end, fps) - 6, sec(end, fps)], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return { opacity: s * out, transform: `translateY(${(1 - s) * rise}px)` };
};

const Eyebrow: React.FC<{ children: React.ReactNode; style?: React.CSSProperties }> = ({ children, style }) => (
  <div style={{ font: `600 22px Inter`, letterSpacing: "0.2em", color: GOLD_LIT, textShadow: "0 1px 6px rgba(0,0,0,.6)", ...style }}>
    {children}
  </div>
);

// 1. Dua Kategori: "Ketidakakuran serius ni terbagi pada dua. Ada syariah, ada teknikal."
const DuaKategori: React.FC<{ a: number; b: number; len: number }> = ({ a, b, len }) => {
  const head = useReveal(0, len, 10);
  const pa = useReveal(a, len);
  const pb = useReveal(b, len);
  const Panel = ({ n, label, st }: { n: string; label: string; st: React.CSSProperties }) => (
    <div style={{ ...st, width: 396, height: 128, background: NAVY_A, borderRadius: 8, display: "flex", alignItems: "center", gap: 22, padding: "0 26px", boxSizing: "border-box", borderBottom: `3px solid ${GOLD}` }}>
      <div style={{ width: 62, height: 62, borderRadius: 31, background: GOLD, color: NAVY, display: "grid", placeItems: "center", font: "700 32px Sora" }}>{n}</div>
      <div style={{ font: "700 42px Sora", color: WHITE, letterSpacing: "0.02em" }}>{label}</div>
    </div>
  );
  return (
    <div style={{ position: "absolute", left: LEFT, top: BAND_TOP, display: "grid", gap: 14 }}>
      <Eyebrow style={head}>KETIDAKAKURAN SERIUS</Eyebrow>
      <div style={{ display: "flex", gap: 20 }}>
        <Panel n="1" label="Syariah" st={pa} />
        <Panel n="2" label="Teknikal" st={pb} />
      </div>
    </div>
  );
};

// 2. Notis Syarikat: "Syarikat dah tutup, tak bagitahu. Syarikat dah berpindah, tak bagitahu."
const Stamp: React.FC<{ at: number }> = ({ at }) => {
  const { frame, fps } = useT();
  const p = interpolate(frame - sec(at, fps), [0, 7], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
  return (
    <div style={{ position: "absolute", right: 18, top: 24, opacity: p, transform: `rotate(-7deg) scale(${1.5 - 0.5 * p})`, border: `3px solid ${GOLD_LIT}`, color: GOLD_LIT, font: "700 22px Inter", letterSpacing: "0.14em", padding: "6px 12px", borderRadius: 4 }}>
      TAK BAGITAHU
    </div>
  );
};
const IconClosed = () => (
  <svg width="46" height="46" viewBox="0 0 48 48" fill="none" stroke={GOLD_LIT} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
    <path d="M8 42V12l16-6 16 6v30" /><path d="M18 42V26h12v16" /><path d="M14 18l20 20M34 18L14 38" />
  </svg>
);
const IconMove = () => (
  <svg width="46" height="46" viewBox="0 0 48 48" fill="none" stroke={GOLD_LIT} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
    <path d="M4 40V20l10-6 10 6v20H4z" /><path d="M28 30h14" /><path d="M36 24l6 6-6 6" />
  </svg>
);
const NotisSyarikat: React.FC<{ c1: number; st1: number; c2: number; st2: number; len: number }> = ({ c1, st1, c2, st2, len }) => {
  const a = useReveal(c1, len);
  const b = useReveal(c2, len);
  const Card = ({ title, icon, st, stampAt }: { title: string; icon: React.ReactNode; st: React.CSSProperties; stampAt: number }) => (
    <div style={{ ...st, position: "relative", width: 396, height: 150, background: NAVY_A, borderRadius: 8, padding: "22px 24px", boxSizing: "border-box", display: "grid", gap: 10, alignContent: "start" }}>
      {icon}
      <div style={{ font: "600 34px Sora", color: WHITE }}>{title}</div>
      <Stamp at={stampAt} />
    </div>
  );
  return (
    <div style={{ position: "absolute", left: LEFT, top: BAND_TOP, display: "flex", gap: 20 }}>
      <Card title="Syarikat tutup" icon={<IconClosed />} st={a} stampAt={st1} />
      <Card title="Syarikat pindah" icon={<IconMove />} st={b} stampAt={st2} />
    </div>
  );
};

// 3. Senarai Premis: "kena tengok pada pergudangan ataupun asrama dan juga kenderaan ... kawasan premis"
const ICONS: Record<string, React.ReactNode> = {
  Gudang: <path d="M6 42V18L24 8l18 10v24M14 42V26h20v16M14 32h20M14 37h20" />,
  Asrama: <path d="M10 42V8h28v34M10 42h28M17 15h4M27 15h4M17 23h4M27 23h4M17 31h4M27 31h4M21 42v-6h6v6" />,
  Kenderaan: <path d="M4 34V14h24v20M28 20h9l7 8v6H28M4 34h40M12 38a4 4 0 1 0 0.1 0M36 38a4 4 0 1 0 0.1 0" />,
  Premis: <path d="M6 20l4-12h28l4 12M6 20h36M6 20v22h36V20M10 20a4 4 0 0 0 8 0a4 4 0 0 0 8 0a4 4 0 0 0 8 0a4 4 0 0 0 8 0M19 42V30h10v12" />,
};
const SenaraiPremis: React.FC<{ items: { at: number; t: string }[]; len: number }> = ({ items, len }) => {
  const head = useReveal(0, len, 10);
  return (
    <div style={{ position: "absolute", left: LEFT, top: BAND_TOP, display: "grid", gap: 14 }}>
      <Eyebrow style={head}>KENA TENGOK JUGA</Eyebrow>
      <div style={{ display: "flex", gap: 14 }}>
        {items.map((it, i) => (
          <Tile key={it.t} label={it.t} at={it.at} len={len} last={i === items.length - 1} />
        ))}
      </div>
    </div>
  );
};
const Tile: React.FC<{ label: string; at: number; len: number; last: boolean }> = ({ label, at, len, last }) => {
  const st = useReveal(at, len, 24);
  return (
    <div style={{ ...st, width: 192, height: 136, background: NAVY_A, borderRadius: 8, display: "grid", placeItems: "center", alignContent: "center", gap: 10, boxSizing: "border-box", border: last ? `2px solid ${GOLD}` : "2px solid transparent" }}>
      <svg width="50" height="50" viewBox="0 0 48 48" fill="none" stroke={GOLD_LIT} strokeWidth="2.6" strokeLinecap="round" strokeLinejoin="round">{ICONS[label]}</svg>
      <div style={{ font: "600 27px Inter", color: WHITE }}>{label}</div>
    </div>
  );
};

// 4. Kad Penutup: comment prompt over the blurred navy freeze.
const KadPenutup: React.FC<{ q: string; share: string }> = ({ q, share }) => {
  const a = useReveal(0.15, 99, 24);
  const b = useReveal(0.35, 99, 24);
  const c = useReveal(0.6, 99, 16);
  const { frame, fps } = useT();
  const rule = interpolate(frame, [sec(0.45, fps), sec(0.9, fps)], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: ease });
  return (
    <AbsoluteFill style={{ justifyContent: "center", alignItems: "flex-start", padding: "0 96px", boxSizing: "border-box", gap: 34, flexDirection: "column", marginTop: -120 }}>
      <Eyebrow style={a}>SOALAN UNTUK ANDA</Eyebrow>
      <div style={{ ...b, font: "700 68px/1.18 Sora", color: WHITE, maxWidth: 860 }}>{q}</div>
      <div style={{ height: 4, width: 160, background: GOLD, transform: `scaleX(${rule})`, transformOrigin: "left" }} />
      <div style={{ ...c, font: "500 36px/1.35 Inter", color: "rgba(255,255,255,.88)", maxWidth: 820 }}>{share}</div>
      <div style={{ ...c, font: "600 26px Inter", letterSpacing: "0.16em", color: GOLD_LIT }}>KOMEN DI BAWAH</div>
    </AbsoluteFill>
  );
};

export const Infografik: React.FC = () => {
  const { fps } = useVideoConfig();
  const G = TL.gfx;
  const seq = (s: number, e: number) => ({ from: sec(s, fps), durationInFrames: sec(e, fps) - sec(s, fps) });
  return (
    <AbsoluteFill style={{ backgroundColor: "transparent" }}>
      <Sequence {...seq(G.duaKategori.s, G.duaKategori.e)}>
        <DuaKategori a={G.duaKategori.a - G.duaKategori.s} b={G.duaKategori.b - G.duaKategori.s} len={G.duaKategori.e - G.duaKategori.s} />
      </Sequence>
      <Sequence {...seq(G.notis.s, G.notis.e)}>
        <NotisSyarikat c1={G.notis.c1 - G.notis.s} st1={G.notis.st1 - G.notis.s} c2={G.notis.c2 - G.notis.s} st2={G.notis.st2 - G.notis.s} len={G.notis.e - G.notis.s} />
      </Sequence>
      <Sequence {...seq(G.premis.s, G.premis.e)}>
        <SenaraiPremis items={G.premis.items.map((i) => ({ ...i, at: i.at - G.premis.s }))} len={G.premis.e - G.premis.s} />
      </Sequence>
      <Sequence {...seq(G.endCard.s, G.endCard.e)}>
        <KadPenutup q={G.endCard.q} share={G.endCard.share} />
      </Sequence>
    </AbsoluteFill>
  );
};

export const INFOGRAFIK_FRAMES = Math.round(TL.duration * TL.fps);
